DO $ddl$ DECLARE s text; BEGIN SELECT pg_get_functiondef(p.oid) INTO s FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='guard_cyber_contract'; s:=replace(s,' AND NEW.maandwaarde=0',''); EXECUTE s; END $ddl$; COMMENT ON FUNCTION public.guard_cyber_contract() IS 'Coulance alleen voor vastgelegd De Directietafel-besluit; maandwaarde is generated en niet beschikbaar in BEFORE-trigger.';